export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;

  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  const t = time;
  const tossHeight = launchSpeed * t - 0.5 * gravity * t * t;
  const tossedVelocity = launchSpeed - gravity * t;
  const tossedAcceleration = -gravity;

  let dropHeight = apexHeight;
  let dropVelocity = 0;
  let dropAcceleration = 0;

  if (t >= apexTime) {
    const dt = t - apexTime;
    dropHeight = apexHeight - 0.5 * gravity * dt * dt;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
  }

  let tossState = "Rising";
  if (t <= 0.05) tossState = "At launch";
  else if (Math.abs(t - apexTime) < 0.05) tossState = "At the top";
  else if (t > apexTime && tossHeight > 0) tossState = "Falling";
  else if (tossHeight <= 0) tossState = "At launch height";

  let dropState = "Held in place";
  if (Math.abs(t - apexTime) < 0.05) dropState = "Just released";
  else if (t > apexTime && dropHeight > 0) dropState = "Falling together";
  else if (dropHeight <= 0) dropState = "At launch height";

  const objects = [];

  // Lanes
  objects.push(...sdk.panel({ x: 30, y: 50, w: 270, h: 330, title: "Toss Lane", state: tossState, id: "lane.toss" }));
  objects.push(...sdk.panel({ x: 340, y: 50, w: 270, h: 330, title: "Drop Lane", state: dropState, id: "lane.drop" }));

  // Axis scale mapping: height 0 to 2.2 m mapped to y from 350 down to 100
  const hMin = 0;
  const hMax = 2.2;
  const yBottom = 350;
  const yTop = 110;
  const heightToY = (h) => yBottom - ((h - hMin) / (hMax - hMin)) * (yBottom - yTop);

  const tossY = heightToY(Math.max(0, tossHeight));
  const dropY = heightToY(Math.max(0, dropHeight));

  // Gate at apex height in Drop lane
  const gateY = heightToY(apexHeight);
  if (t < apexTime) {
    objects.push(sdk.gate("gate", 475, gateY, { open: false, label: "Gate" }));
  } else {
    objects.push(sdk.gate("gate", 475, gateY, { open: true, label: "Gate" }));
  }

  // Balls
  objects.push(sdk.circle("ball.toss", 165, tossY, 24, { role: "primary" }));
  objects.push(sdk.circle("ball.drop", 475, dropY, 24, { role: "secondary" }));

  // Vectors: velocity and acceleration
  objects.push(...sdk.vector("vec.v.toss", { x: 135, y: tossY }, { value: tossedVelocity, direction: "up" }, { scale: 20, label: "v" }));
  objects.push(...sdk.vector(
    "vec.a.toss",
    { x: 195, y: tossY },
    { value: tossedAcceleration, direction: "up" },
    { scale: 5, label: "a" }
  ));

  objects.push(...sdk.vector("vec.v.drop", { x: 445, y: dropY }, { value: dropVelocity, direction: "up" }, { scale: 20, label: "v" }));
  objects.push(...sdk.vector(
    "vec.a.drop",
    { x: 505, y: dropY },
    { value: dropAcceleration, direction: "up" },
    { scale: 5, label: "a" }
  ));

  // Callouts
  objects.push(...sdk.callout(195, tossY - 30, [
    `v: ${sdk.format(tossedVelocity, 2)} m/s`,
    `a: ${sdk.format(tossedAcceleration, 1)} m/s^2`
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(505, dropY - 30, [
    `v: ${sdk.format(dropVelocity, 2)} m/s`,
    `a: ${sdk.format(dropAcceleration, 1)} m/s^2`
  ], { id: "callout.drop" }));

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: tossedVelocity },
        { id: "tossedAcceleration", value: tossedAcceleration },
        { id: "dropVelocity", value: dropVelocity },
        { id: "dropAcceleration", value: dropAcceleration }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      apexTime,
      apexHeight,
      tossedVelocity,
      tossedAcceleration,
      tossedHeight,
      dropVelocity,
      dropAcceleration,
      dropHeight
    }
  };
}
